CREATE TABLE IF NOT EXISTS person(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR_IGNORECASE(200) NOT NULL UNIQUE, display_name VARCHAR(100) NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(30) NOT NULL, branch VARCHAR(60) NOT NULL, active BOOLEAN DEFAULT TRUE, otp_secret VARCHAR(100), marketing BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS product(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(120), category VARCHAR(60), finish VARCHAR(120), dimensions VARCHAR(120), price DECIMAL(14,2) CHECK(price>0), cost DECIMAL(14,2), photo VARCHAR(180), warranty VARCHAR(150));
CREATE TABLE IF NOT EXISTS stock(product_id BIGINT REFERENCES product,branch VARCHAR(60),on_hand INT DEFAULT 0 CHECK(on_hand>=0),held INT DEFAULT 0 CHECK(held>=0 AND held<=on_hand),PRIMARY KEY(product_id,branch));
CREATE TABLE IF NOT EXISTS work(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind VARCHAR(24), stage VARCHAR(32), title VARCHAR(200), person_id BIGINT REFERENCES person, creator BIGINT REFERENCES person, assignee BIGINT REFERENCES person, branch VARCHAR(60), parent_id BIGINT REFERENCES work, detail VARCHAR(2500),amount DECIMAL(14,2) DEFAULT 0, due_date DATE, revision INT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS work_owner ON work(person_id,branch,kind);
CREATE TABLE IF NOT EXISTS item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,work_id BIGINT REFERENCES work,product_id BIGINT REFERENCES product, name VARCHAR(160),qty INT CHECK(qty>0),price DECIMAL(14,2), cost DECIMAL(14,2),received INT DEFAULT 0,returned_qty INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS journal(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,work_id BIGINT REFERENCES work,actor BIGINT REFERENCES person,action VARCHAR(2400),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS money(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,work_id BIGINT REFERENCES work,actor BIGINT REFERENCES person,amount DECIMAL(14,2),ref VARCHAR(120) UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attachment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,work_id BIGINT REFERENCES work,actor BIGINT REFERENCES person,name VARCHAR(150),mime VARCHAR(100),bytes BLOB);
CREATE TABLE IF NOT EXISTS wishlist(person_id BIGINT REFERENCES person, product_id BIGINT REFERENCES product, PRIMARY KEY(person_id,product_id));
CREATE TABLE IF NOT EXISTS return_line(work_id BIGINT PRIMARY KEY REFERENCES work,item_id BIGINT REFERENCES item,quantity INT,restock BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS setting(name VARCHAR(80) PRIMARY KEY,val VARCHAR(500));
CREATE TABLE IF NOT EXISTS payment_intent(provider_id VARCHAR(120) PRIMARY KEY,work_id BIGINT REFERENCES work,amount DECIMAL(14,2),state VARCHAR(16));
ALTER TABLE item ADD COLUMN IF NOT EXISTS shipped INT DEFAULT 0;
CREATE TABLE IF NOT EXISTS plan_material(job_id BIGINT REFERENCES work,product_id BIGINT REFERENCES product,required_qty INT,PRIMARY KEY(job_id,product_id));
CREATE TABLE IF NOT EXISTS inbox(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,person_id BIGINT REFERENCES person, message VARCHAR(2500),work_id BIGINT REFERENCES work,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS restock(person_id BIGINT REFERENCES person,product_id BIGINT REFERENCES product,branch VARCHAR(60),PRIMARY KEY(person_id,product_id,branch));
CREATE TABLE IF NOT EXISTS shipment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,work_id BIGINT REFERENCES work,item_id BIGINT REFERENCES item,qty INT,reference_no VARCHAR(150),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quote_calc(work_id BIGINT PRIMARY KEY REFERENCES work,materials DECIMAL(14,2),labour DECIMAL(14,2),freight DECIMAL(14,2),discount DECIMAL(14,2),approved BOOLEAN,requester BIGINT REFERENCES person);
CREATE TABLE IF NOT EXISTS checkout_key(person_id BIGINT REFERENCES person,request_key VARCHAR(80),work_id BIGINT REFERENCES work,PRIMARY KEY(person_id,request_key));
ALTER TABLE person ADD COLUMN IF NOT EXISTS auth_version INT DEFAULT 1;
CREATE TABLE IF NOT EXISTS bank_match(payment_id BIGINT PRIMARY KEY REFERENCES money,statement_ref VARCHAR(120) UNIQUE,actor BIGINT REFERENCES person,matched_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS route_stop(work_id BIGINT PRIMARY KEY REFERENCES work,vehicle VARCHAR(80),slot DATE,crew VARCHAR(100),volume DECIMAL(12,2));
CREATE TABLE IF NOT EXISTS vehicle(name VARCHAR(80) PRIMARY KEY,branch VARCHAR(60),capacity DECIMAL(12,2));
ALTER TABLE work ADD COLUMN IF NOT EXISTS source VARCHAR(100);
ALTER TABLE work ADD COLUMN IF NOT EXISTS budget DECIMAL(14,2);
ALTER TABLE work ADD COLUMN IF NOT EXISTS buy_days INT;
ALTER TABLE work ADD COLUMN IF NOT EXISTS valid_until DATE;
CREATE TABLE IF NOT EXISTS accounting_period(branch VARCHAR(60) PRIMARY KEY,closed_to DATE);
INSERT INTO accounting_period(branch) SELECT 'Central' WHERE NOT EXISTS(SELECT 1 FROM accounting_period WHERE branch='Central');
INSERT INTO accounting_period(branch) SELECT 'North' WHERE NOT EXISTS(SELECT 1 FROM accounting_period WHERE branch='North');
CREATE TABLE IF NOT EXISTS posting(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,branch VARCHAR(60),work_id BIGINT REFERENCES work,actor BIGINT REFERENCES person,debit VARCHAR(40),credit VARCHAR(40),amount DECIMAL(14,2),memo VARCHAR(220),book_date DATE);
ALTER TABLE stock ADD COLUMN IF NOT EXISTS damaged INT DEFAULT 0;
ALTER TABLE stock ADD COLUMN IF NOT EXISTS display_units INT DEFAULT 0;
CREATE TABLE IF NOT EXISTS stock_count(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT REFERENCES product,branch VARCHAR(60),sellable INT,damaged INT,display_units INT,reason VARCHAR(200),creator BIGINT REFERENCES person,approver BIGINT REFERENCES person,baseline INT,baseline_damaged INT,baseline_display INT);
ALTER TABLE inbox ADD COLUMN IF NOT EXISTS relay_state VARCHAR(20) DEFAULT 'PENDING';
ALTER TABLE inbox ADD COLUMN IF NOT EXISTS attempts INT DEFAULT 0;
ALTER TABLE inbox ADD COLUMN IF NOT EXISTS next_try TIMESTAMP DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE person ADD COLUMN IF NOT EXISTS recovery_hash VARCHAR(120);
CREATE TABLE IF NOT EXISTS site_page(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,branch VARCHAR(60) NOT NULL,slug VARCHAR(80) NOT NULL UNIQUE,title VARCHAR(120) NOT NULL,blocks VARCHAR(32000) NOT NULL,version INT DEFAULT 1,live_title VARCHAR(120),live_blocks VARCHAR(32000),live_version INT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS page_history(page_id BIGINT REFERENCES site_page,revision INT,title VARCHAR(120),blocks VARCHAR(32000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(page_id,revision));
CREATE TABLE IF NOT EXISTS mail_design(branch VARCHAR(60),kind VARCHAR(30),subject VARCHAR(180),body VARCHAR(4000),version INT DEFAULT 1,PRIMARY KEY(branch,kind));
CREATE TABLE IF NOT EXISTS studio_module(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(110) NOT NULL,kind VARCHAR(24) NOT NULL,description VARCHAR(500),config VARCHAR(4000) NOT NULL,enabled BOOLEAN DEFAULT FALSE,version INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS studio_entry(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,module_id BIGINT REFERENCES studio_module,actor BIGINT REFERENCES person,branch VARCHAR(60),answers VARCHAR(8000),stage VARCHAR(24) DEFAULT 'NEW',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS poll_vote(module_id BIGINT REFERENCES studio_module,actor BIGINT REFERENCES person,choice VARCHAR(120),PRIMARY KEY(module_id,actor));
CREATE TABLE IF NOT EXISTS product_question(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT REFERENCES product,actor BIGINT REFERENCES person,branch VARCHAR(60),question VARCHAR(450),answer VARCHAR(1800),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS experience_flag(code VARCHAR(32) PRIMARY KEY,enabled BOOLEAN DEFAULT TRUE);
INSERT INTO experience_flag(code) SELECT 'DISCOVERY' WHERE NOT EXISTS(SELECT 1 FROM experience_flag WHERE code='DISCOVERY');
INSERT INTO experience_flag(code) SELECT 'QUESTIONS' WHERE NOT EXISTS(SELECT 1 FROM experience_flag WHERE code='QUESTIONS');
INSERT INTO experience_flag(code) SELECT 'SHARE' WHERE NOT EXISTS(SELECT 1 FROM experience_flag WHERE code='SHARE');
CREATE TABLE IF NOT EXISTS delivery_window(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,branch VARCHAR(60),starts TIMESTAMP,ends TIMESTAMP,capacity INT,booked INT DEFAULT 0 CHECK(booked>=0 AND booked<=capacity),active BOOLEAN DEFAULT TRUE,UNIQUE(branch,starts,ends));
CREATE TABLE IF NOT EXISTS delivery_booking(work_id BIGINT PRIMARY KEY REFERENCES work,slot_id BIGINT REFERENCES delivery_window,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS price_watch(actor BIGINT REFERENCES person,product_id BIGINT REFERENCES product,target DECIMAL(14,2),PRIMARY KEY(actor,product_id));
CREATE TABLE IF NOT EXISTS price_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT REFERENCES product,previous_price DECIMAL(14,2),new_price DECIMAL(14,2),changed TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE inbox ADD COLUMN IF NOT EXISTS notice_kind VARCHAR(30);
CREATE TABLE IF NOT EXISTS sandbox_order(provider_order VARCHAR(80) PRIMARY KEY,actor BIGINT REFERENCES person,key_id VARCHAR(80),amount_paise BIGINT,status VARCHAR(24),payment_id VARCHAR(80) UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS attempt(email VARCHAR(220) PRIMARY KEY, failures INT, since_at BIGINT);
ALTER TABLE person ADD COLUMN IF NOT EXISTS phone VARCHAR(24) DEFAULT '';
ALTER TABLE person ADD COLUMN IF NOT EXISTS delivery_address VARCHAR(600) DEFAULT '';
ALTER TABLE person ADD COLUMN IF NOT EXISTS delivery_pincode VARCHAR(6) DEFAULT '';
CREATE TABLE IF NOT EXISTS login_token(token_hash CHAR(64) PRIMARY KEY,person_id BIGINT NOT NULL REFERENCES person,auth_version INT NOT NULL,csrf VARCHAR(48) NOT NULL,expires_at BIGINT NOT NULL,pending_mfa VARCHAR(40));
CREATE INDEX IF NOT EXISTS login_token_expiry ON login_token(expires_at);
ALTER TABLE sandbox_order ADD COLUMN IF NOT EXISTS work_id BIGINT REFERENCES work;
CREATE INDEX IF NOT EXISTS sandbox_work ON sandbox_order(work_id,created_at);
ALTER TABLE work ADD COLUMN IF NOT EXISTS payment_method VARCHAR(16) DEFAULT 'OFFLINE';
CREATE TABLE IF NOT EXISTS seed_version(name VARCHAR(60) PRIMARY KEY);
ALTER TABLE product ADD COLUMN IF NOT EXISTS variant_family VARCHAR(100);
ALTER TABLE person ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS catalog_listing(product_id BIGINT,branch VARCHAR(60),name VARCHAR(120),category VARCHAR(60),finish VARCHAR(120),dimensions VARCHAR(120),warranty VARCHAR(150),published BOOLEAN NOT NULL DEFAULT TRUE,revision INT NOT NULL DEFAULT 1,PRIMARY KEY(product_id,branch),FOREIGN KEY(product_id,branch) REFERENCES stock(product_id,branch));
CREATE VIEW IF NOT EXISTS showroom_item AS SELECT p.id,p.sku,coalesce(l.name,p.name) name,coalesce(l.category,p.category) category,coalesce(l.finish,p.finish) finish,coalesce(l.dimensions,p.dimensions) dimensions,coalesce(l.warranty,p.warranty) warranty,p.price,p.cost,p.photo,p.variant_family,st.branch,st.on_hand-st.held available,coalesce(l.published,true) published,coalesce(l.revision,0) listing_revision FROM product p JOIN stock st ON st.product_id=p.id LEFT JOIN catalog_listing l ON l.product_id=p.id AND l.branch=st.branch;
CREATE TABLE IF NOT EXISTS product_feedback(work_id BIGINT PRIMARY KEY REFERENCES work,product_id BIGINT NOT NULL REFERENCES product,author BIGINT NOT NULL REFERENCES person,stars INT NOT NULL CHECK(stars between 1 and 5),author_title VARCHAR(180),author_body VARCHAR(2000),verified BOOLEAN NOT NULL,edited_by_staff BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(product_id,author));
CREATE INDEX IF NOT EXISTS feedback_product ON product_feedback(product_id,work_id);
CREATE TABLE IF NOT EXISTS catalog_price_request(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES product,branch VARCHAR(60),current_price DECIMAL(14,2),proposed DECIMAL(14,2),reason VARCHAR(250),requester BIGINT REFERENCES person,stage VARCHAR(20) DEFAULT 'PENDING',decider BIGINT REFERENCES person,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE login_token ADD COLUMN IF NOT EXISTS active_role VARCHAR(30);
CREATE TABLE IF NOT EXISTS staff_role(person_id BIGINT REFERENCES person,role VARCHAR(30),PRIMARY KEY(person_id,role));
CREATE TABLE IF NOT EXISTS packing_profile(product_id BIGINT,branch VARCHAR(60),revision INT NOT NULL,cartons VARCHAR(900) NOT NULL,upright BOOLEAN NOT NULL,PRIMARY KEY(product_id,branch),FOREIGN KEY(product_id,branch) REFERENCES stock(product_id,branch));
CREATE TABLE IF NOT EXISTS delivery_fit(person_id BIGINT REFERENCES person,product_id BIGINT,branch VARCHAR(60),verdict VARCHAR(25),summary VARCHAR(900),packing_revision INT NOT NULL,lead_id BIGINT REFERENCES work,checked_at TIMESTAMP,PRIMARY KEY(person_id,product_id,branch),FOREIGN KEY(product_id,branch) REFERENCES stock(product_id,branch));
CREATE TABLE IF NOT EXISTS order_fit(work_id BIGINT REFERENCES work,product_id BIGINT REFERENCES product,verdict VARCHAR(25),summary VARCHAR(900),checked_at TIMESTAMP,PRIMARY KEY(work_id,product_id));
ALTER TABLE person ADD COLUMN IF NOT EXISTS email_mfa BOOLEAN DEFAULT FALSE NOT NULL;
UPDATE person SET email_mfa=TRUE,otp_secret=NULL WHERE otp_secret IS NOT NULL;
UPDATE login_token SET pending_mfa=NULL WHERE pending_mfa IS NOT NULL;
CREATE TABLE IF NOT EXISTS account_email_code(person_id BIGINT NOT NULL REFERENCES person,purpose VARCHAR(8) NOT NULL,binding_hash CHAR(64) NOT NULL,auth_version INT NOT NULL,code_hash VARCHAR(100),sent_at BIGINT NOT NULL,window_start BIGINT NOT NULL,sent_count INT NOT NULL,failures INT NOT NULL,PRIMARY KEY(person_id,purpose));
CREATE TABLE IF NOT EXISTS admin_example(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,module VARCHAR(40) NOT NULL,branch VARCHAR(60) NOT NULL,title VARCHAR(140) NOT NULL,detail VARCHAR(350) NOT NULL,stage VARCHAR(60) NOT NULL,metric DECIMAL(14,2) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,deleted BOOLEAN NOT NULL DEFAULT FALSE,revision INT NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS admin_example_scope ON admin_example(branch,module);
ALTER TABLE work ADD COLUMN IF NOT EXISTS enabled BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE work ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE catalog_listing ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE person ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT FALSE;